+/// The `checksum` line of a `SKILL.md` frontmatter, as a byte range
+/// including its line break, and its value.
+fn checksum_line(contents: &str) -> Option<(std::ops::Range<usize>, &str)> {
+    if !contents.starts_with("---") {
+        return None;
+    }
+    let mut start = 0;
+    for (i, line) in contents.split_inclusive('\n').enumerate() {
+        let end = start + line.len();
+        let text = line.trim_end_matches(['\n', '\r']);
+        if i > 0 && text == "---" {
+            return None;
+        }
+        if let Some(value) = text.trim().strip_prefix("checksum:") {
+            return Some((start..end, value.trim().trim_matches('"')));
+        }
+        start = end;
+    }
+    None
+}
+
+/// The skill with its `checksum` line left out: what the checksum covers.
+fn without_checksum(contents: &str) -> String {
+    match checksum_line(contents) {
+        Some((range, _)) => {
+            let mut out = contents.to_string();
+            out.replace_range(range, "");
+            out
+        }
+        None => contents.to_string(),
+    }
+}
+
+/// Whether a skill still matches its checksum: `None` when it carries none,
+/// rendered before checksums.
+fn checksum_matches(contents: &str) -> Option<bool> {
+    let (_, checksum) = checksum_line(contents)?;
+    Some(sha256_hex(without_checksum(contents).as_bytes()) == checksum)
+}
